"use client";
// Adapted from shadcn/ui (MIT). Same compound API; retained panels and one marker.
import * as React from "react";
import { Tabs as Primitive } from "./primitive-tabs";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import "./tabs.css";
function Tabs({ className, ...props }: React.ComponentProps<typeof Primitive.Root>) {
  return <Primitive.Root {...props} className={cn("roc-ui", className)} data-slot="tabs" />;
}
const tabsListVariants = cva("roc-ui", {
  variants: {
    variant: { default: "roc-ui-tabs-default", line: "roc-ui-tabs-line" },
  },
  defaultVariants: { variant: "default" },
});
function TabsList({
  className,
  variant = "default",
  children,
  ...props
}: React.ComponentProps<typeof Primitive.List> &
  VariantProps<typeof tabsListVariants>) {
  return (
    <Primitive.List
      {...props}
      data-slot="tabs-list"
      data-variant={variant}
      className={cn(tabsListVariants({ variant }), className)}
    >
      {children}
    </Primitive.List>
  );
}
function TabsTrigger({
  className,
  ...props
}: React.ComponentProps<typeof Primitive.Trigger>) {
  return (
    <Primitive.Trigger
      {...props}
      data-slot="tabs-trigger"
      className={cn("roc-ui", className)}
    />
  );
}
function TabsContent({
  className,
  value,
  ...props
}: React.ComponentProps<typeof Primitive.Content>) {
  return (
    <Primitive.Content
      {...props}
      value={value}
      forceMount
      data-slot="tabs-content"
      className={cn("roc-ui", className)}
    />
  );
}
export { Tabs, TabsList, TabsTrigger, TabsContent, tabsListVariants };

"use client";
import * as React from "react";
import { Tabs as Base } from "@animate-ui/react/primitives/base-ui/tabs";
import { Direction } from "./primitive-direction";
import { useDirectionContext } from "./primitive-direction-context";
type RootProps = Omit<React.ComponentProps<"div">, "defaultValue" | "dir"> & {
  value?: string; defaultValue?: string; onValueChange?: (value: string) => void;
  orientation?: "horizontal" | "vertical"; dir?: "ltr" | "rtl"; activationMode?: "automatic" | "manual";
};
const Activation = React.createContext(true);
function Root({ onValueChange, activationMode = "automatic", dir, ...props }: RootProps) {
  const direction = useDirectionContext(dir) ?? "ltr";
  return <Direction.DirectionProvider dir={direction}><Activation.Provider value={activationMode === "automatic"}>
    <Base.Root {...props} dir={direction} onValueChange={next => onValueChange?.(String(next))} />
  </Activation.Provider></Direction.DirectionProvider>;
}
function List({ loop = true, ...props }: React.ComponentProps<"div"> & { loop?: boolean }) {
  const activateOnFocus = React.useContext(Activation);
  return <Base.List {...props} activateOnFocus={activateOnFocus} loopFocus={loop} />;
}
function Trigger(props: React.ComponentProps<"button"> & { value: string }) {
  return <Base.Tab {...props} render={(p, state) => <button {...p} data-state={state.active ? "active" : "inactive"} />} />;
}
function Content({ forceMount = true, ...props }: React.ComponentProps<"div"> & { value: string; forceMount?: boolean }) {
  return <Base.Panel {...props} keepMounted={forceMount} data-roc-motion="animate-ui" />;
}
export const Tabs = { Root, List, Trigger, Content };

"use client";
// ROC primitive: sets the reading direction for everything below it.
import * as React from "react";
import { DirectionProvider as BaseProvider } from "@base-ui/react/direction-provider";
import { DirectionContext, useDirectionContext, type Dir } from "./primitive-direction-context";

function DirectionProvider({
  dir,
  children,
}: {
  dir: Dir;
  children?: React.ReactNode;
}) {
  return (
    <DirectionContext.Provider value={dir}>
      <BaseProvider direction={dir}>{children}</BaseProvider>
    </DirectionContext.Provider>
  );
}

/** The direction in effect: the argument, else the provider, else left to right. */
function useDirection(local?: Dir): Dir {
  return useDirectionContext(local) ?? "ltr";
}

export const Direction = { DirectionProvider, useDirection };

"use client";
// ROC primitive: the reading direction set by a DirectionProvider, with no dependencies.
import * as React from "react";

export type Dir = "ltr" | "rtl";

export const DirectionContext = React.createContext<Dir | undefined>(undefined);

/** A `dir` prop wins, then the provider; undefined means "use the CSS direction". */
export function useDirectionContext(local?: Dir): Dir | undefined {
  return local ?? React.useContext(DirectionContext);
}

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

@import "./ui-base.css";
.roc-ui[data-slot="tabs"] {
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
}
.roc-ui[data-slot="tabs"][data-orientation="vertical"] {
  flex-direction: row;
}
.roc-ui[data-slot="tabs-list"] {
  display: inline-flex;
  position: relative;
  align-self: flex-start;
  max-width: 100%;
  padding: 3px;
  gap: 2px;
  border-radius: var(--roc-radius, 8px);
  background: var(--roc-marker, #f0f0f0);
  isolation: isolate;
  overflow: auto;
}
.roc-ui[data-slot="tabs-list"][data-orientation="vertical"] {
  flex-direction: column;
  flex-shrink: 0;
}
.roc-ui[data-slot="tabs-trigger"] {
  position: relative;
  z-index: 1;
  display: inline-flex;
  justify-content: center;
  align-items: center;
  gap: 6px;
  padding: 9px 13px;
  flex: 1;
  border: 0;
  background: transparent;
  border-radius: max(3px, calc(var(--roc-radius, 8px) - 3px));
  font-size: 12px;
  white-space: nowrap;
  cursor: pointer;
  color: var(--roc-muted, #777);
  transition: color var(--roc-motion-fast) var(--roc-motion-ease);
}
.roc-ui[data-slot="tabs-trigger"][data-state="active"] {
  color: var(--roc-ink, #222);
}
.roc-ui [data-slot="tabs-indicator"] {
  position: absolute;
  left: 0;
  top: 0;
  pointer-events: none;
  background: var(--roc-paper, #fff);
  border-radius: max(3px, calc(var(--roc-radius, 8px) - 3px));
  box-shadow: 0 1px 3px #00000010;
}
.roc-ui[data-slot="tabs-list"][data-variant="line"] {
  background: transparent;
}
.roc-ui[data-slot="tabs-list"][data-variant="line"] .roc-ui [data-slot="tabs-indicator"] {
  background: transparent;
  box-shadow: inset 0 -2px var(--roc-accent, var(--roc-ink, #252525));
  border-radius: 0;
}
.roc-ui[data-slot="tabs-content"] {
  flex: 1;
  min-width: 0;
  line-height: 1.65;
}
.roc-ui[data-slot="tabs-content"][hidden] {
  display: none !important;
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="tabs-indicator"],
  .roc-ui[data-slot="tabs-trigger"] {
    transition: none !important;
  }
}

.roc-ui[data-slot="tabs-trigger"][data-state="active"] { background: var(--roc-paper, #fff); box-shadow: 0 1px 3px #00000010; }
.roc-ui[data-slot="tabs-list"][data-variant="line"] [data-state="active"] { background: transparent; box-shadow: inset 0 -2px var(--roc-accent, var(--roc-ink, #252525)); }

@import "./tokens.css";
@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-family: var(--roc-font-body, inherit);
  font-size: var(--roc-text-body, 13px);
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* Shared design tokens for ROC practice cases. Hosts may override any --roc-* token. */
:where(:root) {
  --roc-ink: #252525;
  --roc-muted: #737373;
  --roc-paper: #ffffff;
  --roc-line: #e5e5e5;
  --roc-accent: #1a1a1a;
  --roc-accent-foreground: #ffffff;
  --roc-marker: #efefef;
  --roc-focus: #737373;
  --roc-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --roc-font-heading: var(--roc-font-body);
  --roc-font-control: var(--roc-font-body);
  --roc-font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --roc-text-body: 13px;
  --roc-weight-control: 500;
  --roc-radius: 12px;
  --roc-space-1: 4px;
  --roc-space-2: 8px;
  --roc-space-3: 12px;
  --roc-space-4: 16px;
  --roc-space-6: 24px;
  --roc-space-8: 32px;
  --roc-control-height: 36px;
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}
